for (size_t i = 0; i < PIPE_RECLAIM; ++i)
    SYSCHK(fcntl(pipe_fds[i][0], F_SETPIPE_SZ, 2 * PAGE_SIZE));   // [4] reclaim as pipe_buffer slab page

