{
    if (!p || [...])
        return DEFEX_ALLOW;                   // early-out
    [...]
    check_ped(&dc, p, ...);                   // privilege-escalation detector
    check_integrity(&dc, p, ...);             // file integrity
    check_immutable_root(&dc, ...);           // protected root
    check_trusted_map(&dc, p, ...);           // trusted callers
    [...]
}


