if (UserHandle.getAppId(caller) != Process.myUid()
        && UserHandle.getAppId(caller) != 5250)
    throw new SecurityException("Caller not allowed");
mBackgroundHandler.post(() ->
    SystemProxyAgent.getInstance(mContext).relay(caller, svc, cmd, params));


